static struct { const char *key; conn_t *inst; } table[MAX_KEYS];
static size_t used;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

conn_t *get_conn(const char *key) {        /* the only public way in */
    pthread_mutex_lock(&lock);
    conn_t *c = table_find(key);           /* scan of the keyed table, lock held */
    if (!c) {
        c = conn_open(key);                /* per-key construction */
        table[used++] = (struct entry){ strdup(key), c };
    }
    pthread_mutex_unlock(&lock);
    return c;                              /* every hit returns the same instance */
}
